function validate([initial, target]) {
  if (typeof initial !== 'string' || initial.length < 1 || initial.length > 1000) return 'initial needs 1 to 1000 characters.';
  if (typeof target !== 'string' || target.length < 1 || target.length > 1000) return 'target needs 1 to 1000 characters.';
  if (!/^[a-z]+$/.test(initial) || !/^[a-z]+$/.test(target)) return 'Both strings may contain only lowercase letters.';
  return null;
}

