function minOperations(initial, target) {
  let keep = 0;
  for (let start = 0; start < initial.length; start++) {
    for (let end = start + 1; end <= initial.length; end++) {
      if (target.includes(initial.slice(start, end))) keep = Math.max(keep, end - start);
    }
  }
  return (initial.length - keep) + (target.length - keep);
}

