function generate(rand, size) {
  const word = (length, letters) => Array.from({ length }, () => String.fromCharCode(97 + Math.floor(rand() * letters))).join('');
  if (size === 'large') {
    const letters = [2, 3, 26][Math.floor(rand() * 3)];
    const initial = word(800 + Math.floor(rand() * 201), letters);
    let target = word(800 + Math.floor(rand() * 201), letters);
    if (rand() < 0.5) {
      const length = 1 + Math.floor(rand() * 300);
      const start = Math.floor(rand() * (initial.length - length + 1));
      const at = Math.floor(rand() * (target.length - length + 1));
      target = target.slice(0, at) + initial.slice(start, start + length) + target.slice(at + length);
    }
    return [initial, target];
  }
  const letters = 1 + Math.floor(rand() * 3);
  return [word(1 + Math.floor(rand() * 7), letters), word(1 + Math.floor(rand() * 7), letters)];
}
